package com.medflow.ai;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;import java.net.http.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class GeminiClientTest {
 private final ObjectMapper mapper=new ObjectMapper();
 @SuppressWarnings("unchecked") HttpClient response(int status,String body)throws Exception{HttpClient http=mock(HttpClient.class);HttpResponse<InputStream> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(status);when(response.body()).thenReturn(new ByteArrayInputStream(body.getBytes(StandardCharsets.UTF_8)));when(http.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);return http;}
 private AgentRegistry.Agent agent(){return new AgentRegistry().select("PATIENT","","PATIENT");}
 @Test void missingKeyNeverContactsProvider(){var http=mock(HttpClient.class);var client=new GeminiClient(mapper,"","fixture-model",http);assertFalse(client.configured());assertThrows(ResponseStatusException.class,()->client.explain(agent(),"doctor.directory",2));verifyNoInteractions(http);}
 @Test void providerStatusIsReportedWithoutBodyOrKey()throws Exception{var client=new GeminiClient(mapper,"synthetic-provider-key","fixture-model",response(403,"sensitive-provider-fixture-body"));var error=assertThrows(ResponseStatusException.class,()->client.explain(agent(),"doctor.directory",2));assertTrue(error.getReason().contains("HTTP 403"));assertFalse(error.getReason().contains("sensitive-provider-fixture-body"));assertFalse(error.getReason().contains("synthetic-provider-key"));}
 @Test void providerRateLimitIsNotFabricatedSuccess()throws Exception{var client=new GeminiClient(mapper,"synthetic-provider-key","fixture-model",response(429,"{}"));var error=assertThrows(ResponseStatusException.class,()->client.explain(agent(),"doctor.directory",2));assertEquals(429,error.getStatusCode().value());assertFalse(client.verified());}
 @Test void completedTextMarksOnlyProviderInvocationVerified()throws Exception{var http=response(200,"{\"status\":\"completed\",\"steps\":[{\"type\":\"model_output\",\"content\":[{\"type\":\"text\",\"text\":\"Workflow explanation.\"}]}]}");var client=new GeminiClient(mapper,"synthetic-provider-key","fixture-model",http);assertTrue(client.explain(agent(),"doctor.directory",2).contains("Workflow explanation."));assertTrue(client.verified());verify(http).send(argThat(r->r.uri().toString().equals("https://generativelanguage.googleapis.com/v1beta/interactions")),any(HttpResponse.BodyHandler.class));}
 @Test void modelFunctionCallIsNeverExecuted()throws Exception{var client=new GeminiClient(mapper,"synthetic-provider-key","fixture-model",response(200,"{\"status\":\"requires_action\",\"steps\":[{\"type\":\"function_call\",\"name\":\"shell.exec\"}]}"));assertThrows(ResponseStatusException.class,()->client.explain(agent(),"doctor.directory",2));assertFalse(client.verified());}
 @Test void excessiveProviderResponseIsRejected()throws Exception{var client=new GeminiClient(mapper,"synthetic-provider-key","fixture-model",response(200," ".repeat(64001)));assertThrows(ResponseStatusException.class,()->client.explain(agent(),"doctor.directory",2));}
}
